(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["shakespeare"] = {"ui":{"skip":"Skip to the matter","back":"← Back to AI-gile","lang.button":"Tongue: {name}","lang.dialog":"Choose thy tongue","lang.search":"Search tongues","lang.none":"No tongue matcheth","lang.notYet":"{name} is not yet rendered","theme.aria":"Turn betwixt the light and dark theme","theme.toLight":"Turn to the light theme","theme.toDark":"Turn to the dark theme","index.title":"AI-gile: thy AI dev company, upon one board","index.description":"AI-gile is a kanban board for companies of AI coders. They labour whilst thou sleepest; thou receivest one short pile of matters to decide, to try and to accept.","hero.logoAlt":"AI-gile board emblem","hero.h1.html":"Thy AI dev company, upon one&nbsp;board.","hero.alpha":"🐣 Closed pre-alpha","hero.alphaTitle":"Early and unfinished: thanks for the trying of it!","hero.lede":"They build whilst thou sleepest. Thou wakest to one short pile: a few questions, a few things to try, a purple diamond or two. Click, accept, and back to thy coffee.","dl.windows":"Windows app","dl.browser":"Run it in thy browser","dl.soon":"Coming anon","dl.notify":"🔔 Tell me when it openeth","dl.notifySmall":"Alpha or beta","hero.secondary":"Agile, yet the company needeth never a stand-up coffee. (They hold stand-ups all the same.)","pitch.h2":"AI-gile in as many words as thou wilt","pitch.lede":"Pick a length, from one word to 144. Each length is its own description, writ for that measure. Drag the slider or use the arrow keys.","pitch.rangeLabel":"Length in words","pitch.dice":"🎲 another version","pitch.words.one":"{n} word","pitch.words.other":"{n} words","pitch.letters.one":"{n} letter","pitch.letters.other":"{n} letters","pitch.chars.one":"{n} character","pitch.chars.other":"{n} characters","count.line.html.one":"{n} card upon the board this very hour","count.line.html.other":"{n} cards upon the board this very hour","features.aria":"What it doth","f.pile.h":"One pile for thee","f.pile.html":"<b>For thee</b> holdeth all that awaiteth thee, across every project: questions, things to try, tasks that only a mortal may do. Thy queue telleth what cometh next and how long it taketh.","f.sleep.h":"Companies that labour whilst thou sleepest","f.sleep.p":"Each project hath a lead and a company of AI agents. Comment on a card and the company waketh, doth the work, and handeth it back with steps a weary mortal may follow.","f.tester.h":"An AI tester looketh first","f.tester.p":"Ere aught reacheth thee, a tester followeth the steps in a copy of the app and sheweth what it saw, with a screenshot. Flick through those that passed and accept in a click.","f.proof.h":"Proof, not promises","f.proof.p":"Every hand-over sheweth what changed: the files, the diff, the screenshots. No opening of every app to learn if it be done.","f.chat.h":"Parley with thy leads","f.chat.p":"A Discord-style rail: one icon per project, purple diamonds for what needeth thee. Send a lead an idea; he turneth it into cards and a plan, with a ✅ Go button.","f.tidy.h":"Keepeth itself tidy","f.tidy.p":"Kindred cards fold into one, muddled titles are mended, and a token check keepeth the code lean. Fewer things to switch betwixt, less to ponder.","f.private.h":"Thine, upon thy computer","f.private.li1":"The board runneth on thine own machine and answereth only thee.","f.private.li2":"Private missives betwixt people are end-to-end encrypted.","f.private.li3":"No accounts, no trackers, no cookies.","f.lang.h":"In thy tongue","f.lang.p":"Over 120 tongues, from Dutch, Welsh and Japanese to pirate, Yoda and Klingon, with a quick turn back to English for the developer words.","tl.aria":"Timeline from the first parley to the roadmap","tl.h2":"From the first parley to what cometh next","tl.lede":"True dates and hours, in thine own time zone. After this day it is the plan, with no dates promised.","tl.today":"This day","tl.planned":"planned","tl.cards.one":"{n} card","tl.cards.other":"{n} cards","join.h2":"Join in","join.lede":"AI-gile is built by one small mortal and a great number of patient agents. It is private for now, in a closed alpha with friends. Wouldst thou have a go when it openeth?","join.btn":"Register interest","join.small":"We shall send thee a letter, naught else","footer.tag":"AI-gile. No trackers, no cookies, no stand-up coffee.","footer.licence":"Business licence","footer.status":"Status","form.sending":"Sending…","form.failed":"That availed not: try again anon.","form.offline":"Could not reach AI-gile: try again anon.","interest.title":"AI-gile: tell me when the alpha openeth","interest.description":"Leave thine email to hear when AI-gile's closed alpha or beta openeth.","interest.h1":"🔔 Tell me when it openeth","interest.lede":"AI-gile is in closed pre-alpha. Leave thine email and we shall write once, when there is a place for thee.","interest.email":"Thine email","interest.which":"Which test?","interest.alpha":"Closed alpha: early, rough, many changes","interest.beta":"Beta: steadier, later","interest.both":"Either, whichever cometh first","interest.submit":"Put me on the list","interest.thanks":"Thanks! Thou art on the list.","interest.kept":"Only thine email and the test thou pickedst are kept, for this list alone. No newsletter, no trackers.","licence.title":"AI-gile: business licence","licence.description":"Usest thou AI-gile in thy business? Apply for a free business licence.","licence.h1":"📜 Business licence","licence.lede":"Usest thou AI-gile at work? Tell us who thou art and what thou dost. If it doth some good, the licence is free.","licence.company":"Company","licence.website":"Website","licence.what":"What thou dost","licence.how":"How it helpeth the world","licence.email":"Email","licence.submit":"Apply","licence.thanks":"Thanks! We shall reply by email.","status.title":"AI-gile status","status.h1":"AI-gile status","status.quiet":"All quiet","status.checking":"Checking…","status.offline":"Cannot reach the status service this hour (retrying)","status.updated":"updated {ago}","status.justNow":"e'en now","status.min":"{n} min ago","status.hours":"{n} h ago","status.days":"{n} d ago","live.h2":"Behold it being built, alive","live.caption":"Each card is hid: thou seest the shape of the work, not the words.","live.watching.one":"alive: {n} beholding","live.watching.other":"alive: {n} beholding","live.offline":"The living board doth take a breath. Return anon, good friend.","live.cols":"Backlog|To be done|Afoot|The company doth review|For thee to test|For the company|Done","live.last.now":"Last card moved but now","live.last.min.one":"Last card moved {n} minute ago","live.last.min.other":"Last card moved {n} minutes ago","live.last.hour.one":"Last card moved {n} hour ago","live.last.hour.other":"Last card moved {n} hours ago","live.last.day.one":"Last card moved {n} day ago","live.last.day.other":"Last card moved {n} days ago"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Automatons.","Entrusted."]},{"n":2,"texts":["Robot kanban.","Agents, marshalled.","Ideas, wrought."]},{"n":3,"texts":["Kanban for automatons.","Ideas become deeds.","Free agent kanban."]},{"n":5,"texts":["A board whereon agents toil.","Thou writest cards. Agents build.","Free, local, proven, mildly daft."]},{"n":8,"texts":["A free kanban board where AI agents labour.","Write thine idea. Agents build it. Thou accepteth.","Agile for one mortal and many patient automatons."]},{"n":13,"texts":["A kanban board upon thy computer, where AI agents take up the cards.","Write an idea. A company of agents buildeth it. A tester proveth it.","Free, no accounts, no trackers: a board, some robots, and thou in command."]},{"n":21,"texts":["AI-gile is a kanban board for labouring with AI coding agents. They take up the cards; thou triest and acceptest them.","Each project hath a lead and a company of AI agents. Comment on any card and the company setteth to work.","A free, private to-do board that runneth on thine own computer. The labourers are robots. The one who saith yea is thee."]},{"n":34,"texts":["Thou placest ideas upon a board. A company of AI agents turneth them into working features, proveth them, and handeth them back with steps to try. Naught is done until thou sayest so.","AI-gile is a homespun kanban board that Rich built with much help from the very agents it now governeth. It is free, runneth on thy computer, and is shared with friends, not sold.","Picture a plain kanban board, with columns from Backlog to Done, save that AI agents take up the cards. They report their progress, ask when they stick, and ever await thy thumbs up."]},{"n":55,"texts":["AI-gile is a kanban board where the company is made of AI agents. Each project hath a lead who planneth the work and helpers who build it. When a feature is ready, an AI tester trieth it and taketh a screenshot, then it landeth in thy pile. Accept it, or comment and they rework it.","It began as one mortal's way of keeping watch over many AI coding sessions at once, and grew into a proper board. It runneth on thy machine, needeth no account, and hath no trackers. It is free for friends and the curious. It is also unfinished, so expect rough edges and the odd surprise.","Here is the honest tale. Thou must still have the ideas, and thou must still prove the results. What AI-gile doth is all that lieth betwixt: it keepeth the cards in order, waketh the right agent when thou commentest, sheweth exactly what changed, and gathereth all of it into one short pile for thee."]},{"n":89,"texts":["AI-gile is a free kanban board that thou runnest upon thine own computer. In place of folk, each project hath a company of AI agents: a lead who turneth thine ideas into cards and a plan, and helpers who take up the cards in order of weight. When a thing is built, an AI tester followeth the test steps and sheweth thee what it saw. Then it awaiteth in one pile named For thee. Thou acceptest it, or thou commentest and the company hath another go. Naught ever reacheth Done without thee.","Some things thou mightest not expect. A night watch keepeth the To do column filled whilst thou sleepest, choosing cards that need no answer from thee. A token counter sheweth how much the agents have spent this day and this week, and No Token Mode biddeth them cease their spending. Thou canst send missives to friends, and private missives are end-to-end encrypted. The board speaketh about 120 tongues, Dutch, Flemish, pirate and Klingon among them. None of it costeth a penny, and none is trying to sell it thee.","AI-gile is a small, personal undertaking, not a company. Rich desired to tend several AI coding projects without opening every app to look in on them, so he and the agents built a board for it, then used the board to build the rest of itself. It is in closed pre-alpha, which meaneth it worketh, mostly, for a handful of friends. There is no price page, no newsletter and no plan for growth. If it soundeth useful, thou mayest ask to try it when it openeth a little more."]},{"n":144,"texts":["AI-gile is a kanban board for one mortal and a great many AI agents. It runneth on thine own computer and is wholly free. Thou addest projects, and each project getteth a lead and a small company. Thou chattest with the lead, a little like Discord, and describest an idea; the lead turneth it into cards and a plan, then waiteth for thee to press Go. The company worketh through the cards in order of weight, using a plain command line made for language models. Ere aught cometh back to thee, an AI tester followeth the steps in a copy of the app and attacheth a screenshot. Finished work landeth in thy pile with the changed files and the diff. Thou acceptest it, or thou leavest a comment and the company waketh and tries again. Only thou canst move a card to Done.","A day with AI-gile, roughly. At eventide thou leavest a few comments: this button is in the wrong place, that list should be sorted, might we have a dark mode. Thou goest to bed. The agents read the comments, make the changes, prove them and hand them back to thee. If To do runneth dry, the night watch filleth it from the backlog with cards that need no answer from thee. At morn there is one short pile: a couple of questions and a few things to try, each with steps a sleepy mortal may follow and a screenshot of it working. Thou clickest through, acceptest the good ones and sendest back the rest. A token counter sheweth what it all spent, and No Token Mode is there for lean weeks. Then thou breakfastest, wherein the agents cannot yet help.","First, what AI-gile is not. It is not a startup, it is not for sale, and none is gathering thy data. It is a free board that runneth on thy computer, with no accounts, no trackers and no cookies. What it is: one tidy place to see every AI coding project at once, with a company of agents doing the cards and thee making the decisions. It foldeth related cards together, mendeth muddled titles, and keepeth watch that the code stay lean. It speaketh about 120 tongues, from Dutch and Flemish to pirate and Klingon. Friends may send each other missives, privately and encrypted. It was built by Rich and a great number of patient agents, mostly using itself. It is in closed pre-alpha, so it is rough in places. If it soundeth like merriment, ask kindly and thou mayest enter early."]}],"quips":{"1":"One word. Bold. Perchance too bold.","3":"Three words. Already more honest than most product pages.","8":"Eight words. Still shorter than a stand-up.","21":"The lengths are story points, by the way. Of course they are.","55":"Fifty-five words. Two cards were finished whilst thou readest.","144":"That is the long one. There is no 233. The agents have gone to bed."}},"timeline":{"first-idea.name":"The first idea","first-idea.line":"The very first parley, ere any code did exist.","first-board.name":"First board","first-board.line":"A board that keepeth tally of its own building: cards, columns, drag and drop, projects.","team-roles.name":"Company and roles","team-roles.line":"Agent profiles, company templates, spaces and who doth what.","install.name":"Install and releases","install.line":"A zip a friend may install, self-updates, channels and the rolling back.","usage-saver.name":"Usage saver","usage-saver.line":"Measure what runs cost, keep the code lean, spare thy limit.","friends.name":"Friends and sharing","friends.line":"Private missives, a scrambled relay, invites, roles and shared projects.","languages.name":"Tongues","languages.line":"Every screen text in a tongue file, with Dutch and Flemish first.","ai-tester.name":"AI tester","ai-tester.line":"A tester looketh over every hand-over first and sheweth what it saw.","website.name":"The website","website.line":"aigile.lol, the teaser and this timeline.","streaming.name":"Chat and streaming","streaming.line":"Discord, Twitch, OBS, streamer mode, GIFs and emojis.","no-ai.name":"No AI edition","no-ai.line":"A board for folk who code without AI, and public boards.","night-watch.name":"Night watch","night-watch.line":"A watchman and Scrum Master keep the companies at their task whilst thou sleepest.","p-more.name":"Everything else","p-more.line":"Smaller ideas still awaiting their turn.","p-android.name":"Phone and Android","p-android.line":"Reach thy board from a phone, then a native Android app.","p-release.name":"Alpha and beyond","p-release.line":"Closed alpha, the live site, then beta.","p-languages.name":"More tongues","p-languages.line":"More than a hundred tongues, and an immersion mode for learners.","p-engines.name":"More AI engines","p-engines.line":"Choose Claude, Codex or Gemini for each agent.","p-pro.name":"Pro practice","p-pro.line":"Risk labels, merge gates, incident cards and guard rails.","p-self.name":"Looking after thee","p-self.line":"Tired mode, self-care reminders and 4:20.","p-servers.name":"Servers and scale","p-servers.line":"Global server settings, roles and planning for growth.","p-livestream.name":"Streaming extras","p-livestream.line":"Twitch chat, custom emojis and a public live view."}};
